<?php
require __DIR__.'/config/app.php';
$me=require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){
    csrf_check();$action=$_POST['action']??'';
    try{
        if($action==='read'){$q=db()->prepare('UPDATE notifications SET is_read=1 WHERE id=? AND user_id=?');$q->execute([(int)($_POST['id']??0),$me['id']]);flash('Notification marked as read.');}
        elseif($action==='read_all'){ $q=db()->prepare('UPDATE notifications SET is_read=1 WHERE user_id=? AND is_read=0');$q->execute([$me['id']]);flash('All notifications marked as read.');}
        elseif($action==='delete'){$q=db()->prepare('DELETE FROM notifications WHERE id=? AND user_id=?');$q->execute([(int)($_POST['id']??0),$me['id']]);flash($q->rowCount()?'Notification deleted.':'Notification not found.','success');}
    }catch(Throwable $t){flash('Could not update notifications.','error');}
    go('notifications.php');
}
try{$q=db()->prepare('SELECT id,title,message,is_read,created_at FROM notifications WHERE user_id=? ORDER BY created_at DESC,id DESC');$q->execute([$me['id']]);$rows=$q->fetchAll();$unreadCount=count(array_filter($rows,static fn($row)=>(int)$row['is_read']===0));}catch(Throwable $t){$rows=[];$unreadCount=0;}
$pageTitle='Notifications';$activePage='notifications';$bodyClass=$me['role']==='admin'?'dashboard-page admin-page':($me['role']==='committee'?'dashboard-page committee-page':'dashboard-page');
if($me['role']==='student')$sidebarItems=[['Dashboard','student/dashboard.php','▦'],['Explore Events','events.php','⊙'],['My Applications','student/applications.php','♙'],['My Volunteering','student/volunteering.php','♧'],['My Cultural Activities','student/cultural-activities.php','♬'],['My Profile','student/profile.php','♙'],['Notifications','notifications.php','♧'],['Change Password','student/settings.php','⚙']];
if($me['role']==='committee')$sidebarItems=[];
require __DIR__.'/includes/header.php';
?><div class="dash-layout <?=$me['role']==='admin'?'admin-layout':''?>"><?php require __DIR__.'/includes/sidebar.php';?><main class="content-page admin-content notifications-page"><div class="section-heading"><div><h1>Notifications</h1><p><?=count($rows)?> total · <?=$unreadCount?> unread</p></div><?php if($unreadCount):?><form method="post"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="read_all"><button class="btn outline">Mark all as read</button></form><?php endif;?></div><?php if($rows):?><div class="notification-list"><?php foreach($rows as $notification):?><article class="notification-card <?=$notification['is_read']?'is-read':'is-unread'?>"><span class="notification-symbol"><?=eventhub_icon('bell')?></span><div class="notification-copy"><h2><?=e($notification['title'])?></h2><p><?=e($notification['message'])?></p><time datetime="<?=e(date(DATE_ATOM,strtotime($notification['created_at'])))?>"><?=date('d M Y · g:i A',strtotime($notification['created_at']))?></time></div><div class="notification-actions"><?php if(!(int)$notification['is_read']):?><form method="post"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="read"><input type="hidden" name="id" value="<?=$notification['id']?>"><button class="notification-read" aria-label="Mark <?=e($notification['title'])?> as read" title="Mark as read">✓</button></form><?php endif;?><form method="post" onsubmit="return confirm('Delete this notification?')"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$notification['id']?>"><button class="notification-delete" type="submit" aria-label="Delete <?=e($notification['title'])?>" title="Delete notification">Delete</button></form></div></article><?php endforeach;?></div><?php else:?><div class="empty notifications-empty"><span><?=eventhub_icon('bell')?></span><h2>You're all caught up</h2><p>New event updates and announcements will appear here.</p></div><?php endif;?></main></div><?php require __DIR__.'/includes/footer.php';
